import AppKit

/// App logo and support destination shared by the menu bar, Settings and About screens.
public enum AppBranding {
    public static let appName = "YnShot"

    /// Name of the logo image set in `Assets.xcassets` (generated from the source logo by `Scripts/generate-app-icon.sh`)
    public static let logoAssetName = "AppLogo"

    /// Monochrome template glyph for the menu bar (generated by `Scripts/make-logo.swift glyph`)
    public static let menuBarIconAssetName = "MenuBarIcon"

    /// Maker of YnShot, shown in About and used for support requests
    public static let developerName = "Yash Nandha"
    public static let supportEmail = "yash.vhits@gmail.com"
    public static let supportURL = URL(string: "mailto:\(supportEmail)?subject=YnShot%20Support")!

    // PLACEHOLDER: replace with the published policy pages before shipping (the App Store requires both for subscriptions).
    public static let privacyPolicyURL = URL(string: "https://example.com/syncshot/privacy")!
    public static let termsOfUseURL = URL(string: "https://example.com/syncshot/terms")!

    /// The app logo, or the SF Symbol mark when the logo asset isn't bundled (e.g. `swift run` builds)
    public static func logo(size: CGFloat) -> NSImage {
        let image = NSImage(named: logoAssetName)?.copy() as? NSImage
            ?? NSImage(systemSymbolName: "camera.viewfinder", accessibilityDescription: appName)?
                .withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: size * 0.8, weight: .regular))
            ?? NSImage()
        image.size = NSSize(width: size, height: size)
        return image
    }

    /// Menu bar glyph; template so macOS tints it for light, dark and highlighted menu bars
    public static func menuBarIcon() -> NSImage? {
        let image = NSImage(named: menuBarIconAssetName)
            ?? NSImage(systemSymbolName: "camera.viewfinder", accessibilityDescription: appName)
        image?.isTemplate = true
        image?.size = NSSize(width: 18, height: 18)
        return image
    }

    @MainActor
    public static func openPrivacyPolicy() {
        NSWorkspace.shared.open(privacyPolicyURL)
    }

    @MainActor
    public static func openTermsOfUse() {
        NSWorkspace.shared.open(termsOfUseURL)
    }

    /// Opens the support destination (mail client or browser)
    @MainActor
    public static func contactSupport() {
        NSWorkspace.shared.open(supportURL)
    }
}
